package it.frociart.app;
import java.util.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import static it.frociart.app.FlowModel.*;
public final class FprgExtendedTests {
 static int checks;static void check(boolean value,String text){if(!value)throw new AssertionError(text);checks++;}static String text(String v){return FlowEngine.evaluate(v,Collections.emptyMap()).format();}static String normal(String v){return v.replace("\r\n","\n");}static boolean near(double a,double b){return Math.abs(a-b)<.000001;}
 static void execute(Document d,String[] row){FlowEngine.Runner r=new FlowEngine.Runner(d);List<String> writes=new ArrayList<>();int reads=0;for(int i=0;i<3000&&r.state!=FlowEngine.State.COMPLETED&&r.state!=FlowEngine.State.ERROR;i++){if(r.state==FlowEngine.State.WAITING_FILE){FlowTextFiles.Request req=r.pendingFile();check(r.fileDeferred(req,"Riprovare")&&r.pendingFile()==req,"Deferral keeps capability");if(req.kind==FlowTextFiles.Kind.READ){reads++;check(!r.files.hasRead(),"No input before host grant");check(r.provideFile(req,text(row[2])),"Read fulfilled");}else{writes.add(normal(req.text));check(r.files.outputDraft().equals(req.text),"Exact recoverable draft");check(r.provideFile(req,null),"Save acknowledged");}check(!r.provideFile(req,"stale"),"Stale capability rejected");}else r.step();}
  check(r.state==FlowEngine.State.COMPLETED,"Runtime completes "+row[0]+": "+r.errorMessage);check(normal(r.outputText()).equals(text(row[1])),"Exact console "+row[0]);check(reads==Integer.parseInt(row[9])&&writes.size()==Integer.parseInt(row[10]),"Exact read/save counts");if(!writes.isEmpty())check(String.join("",writes).equals(text(row[3])),"Exact file content");check(near(r.turtle.x(),Double.parseDouble(row[4]))&&near(r.turtle.y(),Double.parseDouble(row[5]))&&near(r.turtle.heading(),Double.parseDouble(row[6])),"Turtle position and heading");check(r.turtle.color().equals(row[8])&&r.turtle.segments().size()==Integer.parseInt(row[7]),"Colour and line count");String[] lines=row[11].isEmpty()?new String[0]:row[11].split(";");for(int i=0;i<lines.length;i++){String[] p=lines[i].split(",");FlowTurtle.Segment s=r.turtle.segments().get(i);check(near(s.x1,Double.parseDouble(p[0]))&&near(s.y1,Double.parseDouble(p[1]))&&near(s.x2,Double.parseDouble(p[2]))&&near(s.y2,Double.parseDouble(p[3]))&&s.color.equals(p[4]),"Every segment exact");}
 }
 public static void main(String[] args)throws Exception{Path root=Paths.get(args[0]);Path runtime=args.length>1?Paths.get(args[1]):root.resolve("../frociart-v1-capabilities/android/app/src/main/assets/PythonRuntime.py");Files.createDirectories(root.resolve("android"));for(String line:Files.readAllLines(root.resolve("cases.tsv"),StandardCharsets.UTF_8)){String[] row=line.split("\t",-1);Path path=root.resolve("fixtures/"+row[0]+".fprg");byte[] original=Files.readAllBytes(path);Document d=FlowgorithmImport.decode(new String(original,StandardCharsets.UTF_8));String before=FlowCodec.encode(d);execute(d,row);check(FlowCodec.encode(d).equals(before)&&Arrays.equals(original,Files.readAllBytes(path)),"Project/source untouched");execute(FlowCodec.decode(before),row);execute(FlowPseudocode.decode(FlowPseudocode.encode(d)),row);Path saved=root.resolve("android/"+row[0]+".frociart");Files.write(saved,before.getBytes(StandardCharsets.UTF_8));execute(FlowCodec.decode(new String(Files.readAllBytes(saved),StandardCharsets.UTF_8)),row);check(!before.contains("PRIVATE_"),"Metadata absent");FlowSource.compile(d);check(FlowPython.generate(FlowSource.compile(d),new String(Files.readAllBytes(runtime),StandardCharsets.UTF_8)).text.length()>0,"Python source accepts imported nodes");}
  try(java.util.stream.Stream<Path> files=Files.list(root.resolve("fixtures"))){for(Path file:(Iterable<Path>)files.filter(p->p.getFileName().toString().startsWith("reject-"))::iterator){boolean rejected=false;try{FlowgorithmImport.decode(new String(Files.readAllBytes(file),StandardCharsets.UTF_8));}catch(IllegalArgumentException e){rejected=e.getMessage().contains("Flowgorithm");}check(rejected,"Atomic diagnostic "+file.getFileName());}}
  Document guarded=FlowgorithmImport.decode("<flowgorithm fileversion=\"4.2\"><function name=\"Main\" type=\"None\" variable=\"\"><parameters/><body><open mode=\"read\" expression=\"&quot;/not-granted/private.txt&quot;\"/></body></function></flowgorithm>");FlowEngine.Runner r=new FlowEngine.Runner(guarded);for(int i=0;i<8&&r.state!=FlowEngine.State.WAITING_FILE;i++)r.step();check(r.state==FlowEngine.State.WAITING_FILE&&!r.files.hasRead(),"Path never auto-opens without host capability");
  System.out.println("FPRG_EXTENDED_ANDROID PASS checks="+checks);
 }
}


